  await salvar(s=>{s.options=s.options||{};s.options[esp]=s.options[esp]||{};s.options[esp][kind]=Array.isArray(s.options[esp][kind])?s.options[esp][kind].filter(x=>x!==v):[]},"Remove "+label+" "+v);
